<?php if(!defined('ABSPATH')){exit;}function leb_get_types_schema(){global $wpdb;$table_name=$wpdb->prefix.'ls_types';$charset_collate=$wpdb->get_charset_collate();return"CREATE TABLE {$table_name} (id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,name varchar(255) NOT NULL,slug varchar(255) NOT NULL,updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (id),UNIQUE KEY slug (slug)) {$charset_collate};";}function leb_get_default_type_rows(){return apply_filters('leb_default_type_rows',[]);}function leb_get_amenities_schema(){global $wpdb;$table_name=$wpdb->prefix.'ls_amenities';$charset_collate=$wpdb->get_charset_collate();return"CREATE TABLE {$table_name} (id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,name varchar(255) NOT NULL,svg_path varchar(2048) DEFAULT NULL,updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (id)) {$charset_collate};";}function leb_get_locations_schema(){global $wpdb;$table_name=$wpdb->prefix.'ls_location';$charset_collate=$wpdb->get_charset_collate();return"CREATE TABLE {$table_name} (id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,name varchar(255) NOT NULL,slug varchar(255) NOT NULL,svg_path varchar(2048) DEFAULT NULL,updated_at datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (id),UNIQUE KEY slug (slug)) {$charset_collate};";}function leb_get_listings_schema(){global $wpdb;$table_name=$wpdb->prefix.'ls_property';return"CREATE TABLE $table_name (id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,host_id bigint(20) UNSIGNED NOT NULL,title varchar(255) NOT NULL,location longtext NOT NULL,address longtext NOT NULL,amenities longtext DEFAULT NULL,type varchar(255) DEFAULT NULL,guests int(11) DEFAULT 0,bedroom int(11) DEFAULT 0,bed int(11) DEFAULT 0,bathroom int(11) DEFAULT 0,description longtext DEFAULT NULL,price bigint(20) DEFAULT 0,map longtext DEFAULT NULL,status varchar(50) DEFAULT 'draft',updated_at datetime DEFAULT '0000-00-00 00:00:00' NOT NULL,PRIMARY KEY (id)) {$wpdb->get_charset_collate()};";}function leb_get_ls_img_schema(){global $wpdb;$table_name=$wpdb->prefix.'ls_img';return"CREATE TABLE $table_name (id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,property_id bigint(20) UNSIGNED NOT NULL,image text NOT NULL,PRIMARY KEY (id),KEY property_id (property_id)) {$wpdb->get_charset_collate()};";}function leb_get_ls_block_date_schema(){global $wpdb;$table_name=$wpdb->prefix.'ls_block_date';$charset_collate=$wpdb->get_charset_collate();return"CREATE TABLE {$table_name} (id bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,property_id bigint(20) UNSIGNED NOT NULL,dates longtext NOT NULL,created_at datetime DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (id)) {$charset_collate};";}function leb_check_table_status($table_name){global $wpdb;$exists=(bool)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = %s AND table_name = %s',$wpdb->dbname,$table_name));$rows_complete=false;if($exists){$default_rows=leb_get_default_type_rows();if(empty($default_rows)){$rows_complete=true;}else{$all_present=true;foreach($default_rows as $row){$slug_exists=$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM `{$table_name}` WHERE slug = %s",$row['slug']));if(!$slug_exists){$all_present=false;break;}}$rows_complete=$all_present;}}return['exists'=>$exists,'rows_complete'=>$rows_complete,];}